124	        assert_eq!(implementation, Address::ZERO);
125	
126	        contract.sender(alice).set_implementation(impl_address);
127	
128	        let implementation = contract.sender(alice).get_implementation();
129	        assert_eq!(implementation, impl_address);
130	        let address = contract.sender(alice).get_address_at_zero_slot();
131	        assert_eq!(address, Address::ZERO);
132	        let address = contract.sender(alice).get_address();
133	        assert_eq!(address, Address::ZERO);
134	
135	        contract.sender(alice).set_address(impl_address);
136	
137	        let implementation = contract.sender(alice).get_implementation();
138	        assert_eq!(implementation, impl_address);
139	        let address = contract.sender(alice).get_address_at_zero_slot();
140	        assert_eq!(address, impl_address);
141	        let address = contract.sender(alice).get_address();
142	        assert_eq!(address, impl_address);
143	
144	        contract.sender(alice).set_address_at_zero_slot(alice);
145	
146	        let implementation = contract.sender(alice).get_implementation();
147	        assert_eq!(implementation, impl_address);
148	        let address = contract.sender(alice).get_address_at_zero_slot();
149	        assert_eq!(address, alice);
150	        let address = contract.sender(alice).get_address();
151	        assert_eq!(address, alice);
152	    }
