70	/// Returns the address that signed a hashed message (`hash`).
71	///
72	/// # Arguments
73	///
74	/// * `context` - Execution context for making static calls.
75	/// * `hash` - Hash of the message.
76	/// * `v` - `v` value from the signature.
77	/// * `r` - `r` value from the signature.
78	/// * `s` - `s` value from the signature.
79	///
80	/// # Errors
81	///
82	/// * [`Error::InvalidSignatureS`] - If the `s` value is grater than
83	///   [`SIGNATURE_S_UPPER_BOUND`].
84	/// * [`Error::InvalidSignature`] - If the recovered address is
85	///   [`Address::ZERO`].
86	///
87	/// # Panics
88	///
89	/// * If the `ecRecover` precompile fails to execute.
90	pub fn recover(
91	    context: impl StaticCallContext,
92	    hash: B256,
93	    v: u8,
94	    r: B256,
95	    s: B256,
96	) -> Result<Address, Error> {
97	    check_if_malleable(&s)?;
98	    // If the signature is valid (and not malleable), return the signer address.
99	    _recover(context, hash, v, r, s)
100	}
