102	/// Calls `ecRecover` EVM precompile.
103	///
104	/// The `ecRecover` EVM precompile allows for malleable (non-unique) signatures:
105	/// this function rejects them by requiring the `s` value to be in the lower
106	/// half order, and the `v` value to be either 27 or 28.
107	///
108	/// # Arguments
109	///
110	/// * `context` - Execution context for making static calls.
111	/// * `hash` - Hash of the message.
112	/// * `v` - `v` value from the signature.
113	/// * `r` - `r` value from the signature.
114	/// * `s` - `s` value from the signature.
115	///
116	/// # Errors
117	///
118	/// * [`Error::InvalidSignature`] - If the recovered address is
119	///   [`Address::ZERO`].
120	///
121	/// # Panics
122	///
123	/// * If the `ecRecover` precompile fails to execute.
124	fn _recover(
125	    context: impl StaticCallContext,
126	    hash: B256,
127	    v: u8,
128	    r: B256,
129	    s: B256,
130	) -> Result<Address, Error> {
131	    let calldata = encode_calldata(hash, v, r, s);
132	
133	    if v == 0 || v == 1 {
134	        // `ecRecover` panics for these values but following the Solidity tests
135	        // https://github.com/OpenZeppelin/openzeppelin-contracts/blob/master/test/utils/cryptography/ECDSA.test.js
136	        // it should return `ECDSAInvalidSignature` error.
137	        return Err(ECDSAInvalidSignature {}.into());
138	    }
139	
140	    let recovered = call::static_call(context, ECRECOVER_ADDR, &calldata)
141	        .expect("should call `ecRecover` precompile");
142	
143	    let recovered = Address::from_slice(&recovered[12..]);
144	
145	    if recovered.is_zero() {
146	        return Err(ECDSAInvalidSignature {}.into());
147	    }
148	    Ok(recovered)
149	}
150	
151	/// Encodes call data for `ecRecover` EVM precompile.
152	///
153	/// # Arguments
154	///
155	/// * `hash` - Hash of the message.
156	/// * `v` - `v` value from the signature.
157	/// * `r` - `r` value from the signature.
158	/// * `s` - `s` value from the signature.
159	fn encode_calldata(hash: B256, v: u8, r: B256, s: B256) -> Vec<u8> {
160	    let calldata = EcRecoverData { hash, v, r, s };
161	    EcRecoverData::abi_encode(&calldata)
162	}
163	
164	/// Validates the `s` value of a signature.
165	///
166	/// EIP-2 still allows signature malleability for `ecRecover` precompile.
167	///
168	/// Remove this possibility and make the signature unique.
169	///
170	/// Appendix F in the [Ethereum Yellow paper], defines the valid range for s in
171	/// (301): 0 < s < secp256k1n ÷ 2 + 1, and for v in (302): v ∈ {27, 28}.
172	///
173	/// Most signatures from current libraries generate a unique signature
174	/// with an s-value in the lower half order.
175	///
176	/// If your library generates malleable signatures,
177	/// such as s-values in the upper range, calculate a new s-value
178	/// with 0xFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFFEBAAEDCE6AF48A03BBFD25E8CD0364141 -
179	/// s1, and flip v from 27 to 28 or vice versa.
180	///
181	/// If your library also generates signatures with 0/1 for v instead 27/28,
182	/// add 27 to v to accept these malleable signatures as well.
183	///
184	/// # Arguments
185	///
186	/// * `s` - `s` value from the signature.
187	///
188	/// # Errors
189	///
190	/// * [`Error::InvalidSignatureS`] - If the `s` value is greater than
191	///   [`SIGNATURE_S_UPPER_BOUND`].
192	///
193	/// [Ethereum Yellow paper]: https://ethereum.github.io/yellowpaper/paper.pdf
194	fn check_if_malleable(s: &B256) -> Result<(), Error> {
195	    let s_u256 = U256::from_be_slice(s.as_slice());
196	    if s_u256 > SIGNATURE_S_UPPER_BOUND {
197	        return Err(ECDSAInvalidSignatureS { s: *s }.into());
198	    }
199	    Ok(())
200	}
201	
