1	//! [EIP-712](https://eips.ethereum.org/EIPS/eip-712) is a standard for hashing
2	//! and signing typed structured data.
3	//!
4	//! The implementation of the domain separator was designed to be as efficient
5	//! as possible while still properly updating the chain id to protect against
6	//! replay attacks on an eventual fork of the chain.
7	//!
8	//! NOTE: This contract implements the version of the encoding known as "v4", as
9	//! implemented by the JSON RPC method [`eth_signTypedDataV4`] in `MetaMask`.
10	//!
11	//! [`eth_signTypedDataV4`]: https://docs.metamask.io/guide/signing-data.html
12	
13	use alloc::{borrow::ToOwned, string::String, vec::Vec};
14	use stylus_sdk::prelude::HostAccess;
15	use stylus_sdk::prelude::public;
16	
17	use alloy_primitives::{keccak256, Address, B256, U256};
18	use alloy_sol_types::{sol, SolType};
19	
20	
21	/// Keccak-256 hash of the EIP-712 domain separator type string.
22	const TYPE_HASH: [u8; 32] =
23	    keccak_const::Keccak256::new()
24	        .update(b"EIP712Domain(string name,string version,uint256 chainId,address verifyingContract)")
25	        .finalize();
26	
27	/// Field for the domain separator.
28	const FIELDS: [u8; 1] = [0x0f];
29	
30	/// Salt for the domain separator.
31	const SALT: [u8; 32] = [0u8; 32];
32	
33	/// Prefix for ERC-191 version with `0x01`.
34	const TYPED_DATA_PREFIX: [u8; 2] = [0x19, 0x01];
35	
36	/// Tuple for the domain separator.
37	type DomainSeparatorTuple = sol! {
38	    tuple(bytes32, bytes32, bytes32, uint256, address)
39	};
40	
41	/// Returns the keccak256 digest of an EIP-712 typed data (ERC-191 version
42	/// `0x01`).
43	///
44	/// The digest is calculated from a `domain_separator` and a `struct_hash`, by
45	/// prefixing them with `[TYPED_DATA_PREFIX]` and hashing the result. It
46	/// corresponds to the hash signed by the [eth_signTypedData] JSON-RPC method as
47	/// part of EIP-712.
48	///
49	/// [eth_signTypedData]: https://eips.ethereum.org/EIPS/eip-712
50	#[must_use]
51	pub fn to_typed_data_hash(
52	    domain_separator: &[u8; 32],
53	    struct_hash: &[u8; 32],
54	) -> B256 {
55	    let mut preimage = [0u8; 66];
56	    preimage[..2].copy_from_slice(&TYPED_DATA_PREFIX);
57	    preimage[2..34].copy_from_slice(domain_separator);
58	    preimage[34..].copy_from_slice(struct_hash);
59	    keccak256(preimage)
60	}
61	
62	/// EIP-712 Contract interface.
63	pub trait IEip712: HostAccess {
64	    /// Immutable name of EIP-712 instance.
65	    const NAME: &'static str;
66	    /// Hashed name of EIP-712 instance.
67	    const HASHED_NAME: [u8; 32] =
68	        keccak_const::Keccak256::new().update(Self::NAME.as_bytes()).finalize();
69	
70	    /// Immutable version of EIP-712 instance.
71	    const VERSION: &'static str;
72	    /// Hashed version of EIP-712 instance.
73	    const HASHED_VERSION: [u8; 32] = keccak_const::Keccak256::new()
74	        .update(Self::VERSION.as_bytes())
75	        .finalize();
76	
77	    /// Returns chain id.
78	    #[must_use]
79	    fn chain_id(&self) -> U256 {
80	        U256::from(self.vm().chain_id())
81	    }
82	
83	    /// Returns the contract's address.
84	    #[must_use]
85	    fn contract_address(&self) -> Address {
86	        self.vm().contract_address()
87	    }
88	
89	    /// Returns the fields and values that describe the domain separator used by
90	    /// this contract for EIP-712 signature.
91	    ///
92	    /// # Arguments
93	    ///
94	    /// * `&self` - Read access to the contract's state.
95	    fn eip712_domain(
96	        &self,
97	    ) -> ([u8; 1], String, String, U256, Address, [u8; 32], Vec<U256>) {
98	        (
99	            FIELDS,
100	            Self::NAME.to_owned(),
101	            Self::VERSION.to_owned(),
102	            self.chain_id(),
103	            self.contract_address(),
104	            SALT,
105	            Vec::new(),
106	        )
107	    }
108	
109	    /// Returns the domain separator for the current chain.
110	    ///
111	    /// # Arguments
112	    ///
113	    /// * `&self` - Read access to the contract's state.
114	    fn domain_separator_v4(&self) -> B256 {
115	        let encoded = DomainSeparatorTuple::abi_encode(&(
116	            TYPE_HASH,
117	            Self::HASHED_NAME,
118	            Self::HASHED_VERSION,
119	            self.chain_id(),
120	            self.contract_address(),
121	        ));
122	
123	        keccak256(encoded)
124	    }
125	
126	    /// Given an already [hashed struct], this function returns the hash of the
127	    /// fully encoded EIP-712 message for this domain.
128	    ///
129	    /// [hashed struct]: https://eips.ethereum.org/EIPS/eip-712#definition-of-hashstruct
130	    ///
131	    /// # Arguments
132	    ///
133	    /// * `&self` - Read access to the contract's state.
134	    fn hash_typed_data_v4(&self, struct_hash: B256) -> B256 {
135	        let domain_separator = self.domain_separator_v4();
136	        to_typed_data_hash(&domain_separator, &struct_hash)
137	    }
138	}
139	
140	#[cfg(test)]
141	mod tests {
142	    use alloy_primitives::{address, b256, uint, Address, U256};
143	
144	    use super::{to_typed_data_hash, IEip712, FIELDS, SALT};
145	
146	    const CHAIN_ID: U256 = uint!(42161_U256);
147	
148	    const CONTRACT_ADDRESS: Address =
149	        address!("000000000000000000000000000000000000dEaD");
150	
151	    #[derive(Default)]
152	    struct TestEIP712;
153	
154	    impl IEip712 for TestEIP712 {
155	        const NAME: &'static str = "A Name";
156	        const VERSION: &'static str = "1";
