185	        );
186	        // bytes32("stylus");
187	        let struct_hash = b256!(
188	            "7379746c75730000000000000000000000000000000000000000000000000000"
189	        );
190	        let expected = b256!(
191	            "cefc47137f8165d8270433dd62e395f5672966b83a113a7bb7b2805730a2197e"
192	        );
193	
194	        assert_eq!(
195	            expected,
196	            to_typed_data_hash(&domain_separator, &struct_hash),
197	        );
198	    }
199	}
