1	//! Pausable Contract.
2	//!
3	//! Contract module which allows implementing an emergency stop mechanism
4	//! that can be triggered by an authorized account.
5	//!
6	//! It provides functions [`Pausable::when_not_paused`]
7	//! and [`Pausable::when_paused`],
8	//! which can be added to the functions of your contract.
9	//!
10	//! Note that your contract will not be pausable by simply including this
11	//! module, only once and where you use [`Pausable::when_not_paused`].
12	//!
13	//! Note that [`Pausable::pause`] and [`Pausable::unpause`] methods are not
14	//! exposed by default.
15	//! You should expose them manually in your contract's abi.
16	
17	use alloc::{vec, vec::Vec};
18	
19	pub use sol::*;
20	use stylus_sdk::{stylus_core::calls::errors::MethodError, prelude::*, storage::StorageBool};
21	
22	#[cfg_attr(coverage_nightly, coverage(off))]
23	mod sol {
24	    use alloy_sol_macro::sol;
25	
26	    sol! {
27	        /// Emitted when pause is triggered by `account`.
28	        #[derive(Debug)]
29	        #[allow(missing_docs)]
30	        event Paused(address account);
31	
32	        /// Emitted when the pause is lifted by `account`.
33	        #[derive(Debug)]
34	        #[allow(missing_docs)]
35	        event Unpaused(address account);
36	    }
37	
38	    sol! {
39	        /// Indicates an error related to the operation that failed
40	        /// because the contract is paused.
41	        #[derive(Debug)]
42	        #[allow(missing_docs)]
43	        error EnforcedPause();
44	
45	        /// Indicates an error related to the operation that failed
46	        /// because the contract is not paused.
47	        #[derive(Debug)]
48	        #[allow(missing_docs)]
49	        error ExpectedPause();
50	    }
51	}
52	
53	/// A Pausable error.
54	#[derive(SolidityError, Debug)]
55	pub enum Error {
56	    /// Indicates an error related to the operation that failed
57	    /// because the contract had been in `Paused` state.
58	    EnforcedPause(EnforcedPause),
59	    /// Indicates an error related to the operation that failed
60	    /// because the contract had been in `Unpaused` state.
61	    ExpectedPause(ExpectedPause)}
62	
63	impl MethodError for Error {
64	    fn encode(self) -> alloc::vec::Vec<u8> {
65	        self.into()
66	    }
67	}
68	
69	/// State of a [`Pausable`] Contract.
70	#[storage]
71	pub struct Pausable {
72	    /// Indicates whether the contract is `Paused`.
73	    pub(crate) paused: StorageBool}
74	
75	/// Pausable interface.
76	#[public]
77	pub trait IPausable {
78	    /// Returns true if the contract is paused, and false otherwise.
79	    ///
80	    /// # Arguments
81	    ///
82	    /// * `&self` - Read access to the contract's state.
83	    fn paused(&self) -> bool;
84	}
85	
86	#[public]
87	#[implements(IPausable)]
88	impl Pausable {}
89	
90	#[public]
91	impl IPausable for Pausable {
92	    fn paused(&self) -> bool {
93	        self.paused.get()
94	    }
95	}
96	
97	impl Pausable {
98	    /// Triggers `Paused` state.
99	    ///
100	    /// # Arguments
101	    ///
102	    /// * `&mut self` - Write access to the contract's state.
103	    ///
104	    /// # Errors
105	    ///
106	    /// * [`Error::EnforcedPause`] - If the contract is in `Paused` state.
107	    pub fn pause(&mut self) -> Result<(), Error> {
108	        self.when_not_paused()?;
109	        self.paused.set(true);
110	        self.vm().log(Paused { account: self.vm().msg_sender() });
111	        Ok(())
112	    }
113	
114	    /// Triggers `Unpaused` state.
115	    ///
116	    /// # Arguments
117	    ///
118	    /// * `&mut self` - Write access to the contract's state.
119	    ///
120	    /// # Errors
121	    ///
122	    /// * [`Error::ExpectedPause`] - If the contract is in `Unpaused` state.
123	    pub fn unpause(&mut self) -> Result<(), Error> {
124	        self.when_paused()?;
125	        self.paused.set(false);
126	        self.vm().log(Unpaused { account: self.vm().msg_sender() });
