2	//!
3	//! Nonces will only increment.
4	
5	use alloc::{vec, vec::Vec};
6	
7	use alloy_primitives::{uint, Address, U256};
8	use stylus_sdk::{stylus_core::calls::errors::MethodError, prelude::*, storage::{StorageMap, StorageU256}};
