12	const ONE: U256 = uint!(1_U256);
13	
14	pub use sol::*;
15	#[cfg_attr(coverage_nightly, coverage(off))]
16	mod sol {
17	    use alloy_sol_macro::sol;
18	
19	    sol! {
20	        /// The nonce used for an `account` is not the expected current nonce.
21	        #[derive(Debug)]
22	        #[allow(missing_docs)]
23	        error InvalidAccountNonce(address account, uint256 current_nonce);
24	    }
25	}
