39	/// State of a [`Nonces`] Contract.
40	#[storage]
41	pub struct Nonces {
42	    /// Mapping from address to its nonce.
43	    pub(crate) nonces: StorageMap<Address, StorageU256>}
44	
45	/// Interface for [`Nonces`]
46	#[public]
47	pub trait INonces {
48	    /// Returns the unused nonce for the given account.
49	    ///
50	    /// # Arguments
51	    ///
52	    /// * `&self` - Read access to the contract's state.
53	    /// * `owner` - The address for which to return the nonce.
54	    #[must_use]
55	    fn nonces(&self, owner: Address) -> U256;
56	}
57	
58	#[public]
59	#[implements(INonces)]
60	impl Nonces {}
61	
62	#[public]
63	impl INonces for Nonces {
64	    fn nonces(&self, owner: Address) -> U256 {
65	        self.nonces.get(owner)
66	    }
67	}
68	
69	impl Nonces {
70	    /// Consumes a nonce for the given `account`.
71	    ///
72	    /// # Arguments
73	    ///
74	    /// * `&mut self` - Write access to the contract's state.
75	    /// * `owner` - The address for which to consume the nonce.
76	    ///
77	    /// # Panics
78	    ///
79	    /// * If the nonce for the given `owner` exceeds [`U256::MAX`].
80	    pub fn use_nonce(&mut self, owner: Address) -> U256 {
81	        let nonce = self.nonces.get(owner);
82	
83	        self.nonces
84	            .setter(owner)
85	            .add_assign_checked(ONE, "nonce should not exceed `U256::MAX`");
86	
87	        nonce
88	    }
89	
90	    /// Same as `use_nonce` but checking that the `nonce` is the next valid for
91	    /// the owner.
92	    ///
93	    /// # Arguments
94	    ///
95	    /// * `&mut self` - Write access to the contract's state.
96	    /// * `owner` - The address for which to consume the nonce.
97	    /// * `nonce` - The nonce to consume.
98	    ///
99	    /// # Errors
100	    ///
101	    /// * [`Error::InvalidAccountNonce`] - Returns an error if the `nonce` is
102	    ///   not the next valid nonce for the owner.
103	    ///
104	    /// # Panics
105	    ///
106	    /// * If the nonce for the given `owner` exceeds [`U256::MAX`].
107	    pub fn use_checked_nonce(
108	        &mut self,
109	        owner: Address,
110	        nonce: U256,
111	    ) -> Result<(), Error> {
112	        let current_nonce = self.use_nonce(owner);
113	
114	        if nonce != current_nonce {
115	            return Err(Error::InvalidAccountNonce(InvalidAccountNonce {
116	                account: owner,
117	                current_nonce}));
118	        }
119	
120	        Ok(())
121	    }
122	}
