10	/// Trait for calling other contracts.
11	/// Users should rarely implement this trait outside of proc macros.
12	pub trait CallContext {
13	    /// Amount of gas to supply the call.
14	    /// Note: values are clipped to the amount of gas remaining.
15	    fn gas(&self) -> u64;
16	}
17	
18	/// Trait for calling the `view` or `pure` methods of other contracts.
19	/// Users should rarely implement this trait outside of proc macros.
20	pub trait StaticCallContext: CallContext {}
21	
22	/// Trait for calling the mutable methods of other contracts.
23	/// Users should rarely implement this trait outside of proc macros.
24	///
25	/// # Safety
26	///
27	/// The type initializer must be a [`TopLevelStorage`][TLS] to prevent aliasing in cases of
28	/// reentrancy.
29	///
30	/// [TLS]: stylus_core::storage::TopLevelStorage
31	pub unsafe trait MutatingCallContext: CallContext {
32	    /// Amount of ETH in wei to give the other contract.
33	    fn value(&self) -> U256;
34	}
35	
36	/// Trait for calling the `write` methods of other contracts.
37	/// Users should rarely implement this trait outside of proc macros.
38	///
39	/// Note: any implementations of this must return zero for [`MutatingCallContext::value`].
40	pub trait NonPayableCallContext: MutatingCallContext {}
41	
42	/// Enables configurable calls to other contracts.
43	#[derive(Debug, Clone)]
44	pub struct Call<const MUTATING: bool = false, const HAS_VALUE: bool = false> {
45	    gas: u64,
46	    value: Option<U256>,
47	}
48	
49	impl<const MUTATING: bool, const HAS_VALUE: bool> Call<MUTATING, HAS_VALUE> {
50	    /// Amount of gas to supply the call.
51	    /// Values greater than the amount provided will be clipped to all gas left.
52	    pub fn gas(self, gas: u64) -> Self {
53	        Self { gas, ..self }
54	    }
55	
56	    /// Amount of ETH in wei to give the other contract.
57	    /// Note: adding value will prevent calls to non-payable methods.
58	    pub fn value(self, value: U256) -> Call<true, true> {
59	        Call {
60	            value: Some(value),
61	            gas: self.gas,
62	        }
63	    }
64	}
65	
66	impl<const MUTATING: bool, const HAS_VALUE: bool> CallContext for Call<MUTATING, HAS_VALUE> {
67	    fn gas(&self) -> u64 {
68	        self.gas
69	    }
70	}
71	
72	impl StaticCallContext for Call<false, false> {}
73	
74	impl NonPayableCallContext for Call<true, false> {}
75	
76	unsafe impl<const HAS_VALUE: bool> MutatingCallContext for Call<true, HAS_VALUE> {
77	    fn value(&self) -> U256 {
78	        self.value.unwrap_or_default()
79	    }
80	}
81	
82	impl Default for Call<false, false> {
83	    fn default() -> Self {
84	        Self::new()
85	    }
86	}
87	
88	impl Call<false, false> {
89	    pub fn new() -> Self {
90	        Self {
91	            gas: u64::MAX,
92	            value: None,
93	        }
94	    }
95	}
96	
97	impl Call<true, false> {
98	    pub fn new_mutating(_storage: &mut impl TopLevelStorage) -> Self {
99	        Self {
100	            gas: u64::MAX,
101	            value: None,
102	        }
103	    }
104	}
105	
106	impl Call<true, true> {
107	    pub fn new_payable(_storage: &mut impl TopLevelStorage, value: U256) -> Self {
108	        Self {
109	            gas: u64::MAX,
110	            value: Some(value),
111	        }
112	    }
113	}
