6	use alloc::vec::Vec;
7	
8	use alloy_sol_types::{Panic, PanicKind, SolError};
9	
10	/// Represents error data when a call fails.
11	#[derive(Debug, PartialEq)]
12	pub enum Error {
13	    /// Revert data returned by the other contract.
14	    Revert(Vec<u8>),
15	    /// Failure to decode the other contract's return data.
16	    AbiDecodingFailed(alloy_sol_types::Error),
17	}
18	
19	impl From<alloy_sol_types::Error> for Error {
20	    fn from(err: alloy_sol_types::Error) -> Self {
21	        Error::AbiDecodingFailed(err)
22	    }
23	}
24	
25	/// Encode an error.
26	///
27	/// This is useful so that users can use `Error` as a variant in their error
28	/// types. It should not be necessary to implement this.
29	pub trait MethodError {
30	    /// Users should not have to call this.
31	    fn encode(self) -> Vec<u8>;
32	}
33	
34	impl MethodError for Error {
35	    #[inline]
36	    fn encode(self) -> Vec<u8> {
37	        From::from(self)
38	    }
39	}
40	
41	impl<T: SolError> MethodError for T {
42	    #[inline]
43	    fn encode(self) -> Vec<u8> {
44	        SolError::abi_encode(&self)
45	    }
46	}
47	
48	impl From<Error> for Vec<u8> {
49	    fn from(err: Error) -> Vec<u8> {
50	        match err {
51	            Error::Revert(data) => data,
52	            #[allow(unused)]
53	            Error::AbiDecodingFailed(err) => Panic::from(PanicKind::Generic).abi_encode(),
54	        }
55	    }
56	}
