646	impl RawLogAccess for TestVM {
647	    fn emit_log(&self, input: &[u8], num_topics: usize) {
648	        let (topics_data, data) = input.split_at(num_topics * 32);
649	        let mut topics = Vec::with_capacity(num_topics);
650	
651	        for chunk in topics_data.chunks(32) {
652	            let mut bytes = [0u8; 32];
653	            bytes.copy_from_slice(chunk);
654	            topics.push(B256::from(bytes));
655	        }
656	
657	        self.state
658	            .borrow_mut()
659	            .emitted_logs
660	            .push((topics, data.to_vec()));
661	    }
662	
663	    fn raw_log(&self, topics: &[B256], data: &[u8]) -> Result<(), &'static str> {
664	        self.state
665	            .borrow_mut()
666	            .emitted_logs
667	            .push((topics.to_vec(), data.to_vec()));
668	        Ok(())
669	    }
670	}
