1	//! Standard math utilities missing in `alloy_primitives`.
2	use alloy_primitives::{uint, U256, U512};
3	
4	/// Trait for standard math utilities missing in `alloy_primitives`.
5	pub trait Math {
6	    /// Returns the square root of a number. If the number is not a perfect
7	    /// square, the value is rounded towards zero.
8	    /// This method is based on Newton's method for computing square roots; the
9	    /// algorithm is restricted to only using integer operations.
10	    ///
11	    /// # Arguments
12	    ///
13	    /// * `self` - value to perform square root operation onto.
14	    #[must_use]
15	    fn sqrt(self) -> Self;
16	
17	    /// Returns the average of two numbers. The result is rounded towards zero.
18	    ///
19	    /// # Arguments
20	    ///
21	    /// * `self` - first value to compute average.
22	    /// * `rhs` - second value to compute average.
23	    #[must_use]
24	    fn average(self, rhs: Self) -> Self;
25	
26	    /// Calculates floor(`self` * `y` / `denominator`) with full precision,
27	    /// following the selected `rounding` direction.
28	    ///
29	    /// # Arguments
30	    ///
31	    /// * `self` - first value to compute the result.
32	    /// * `y` - second value to compute the result.
33	    /// * `denominator` - denominator of the division.
34	    /// * `rounding` - rounding technique to use in calculation.
35	    #[must_use]
36	    fn mul_div(self, y: Self, denominator: Self, rounding: Rounding) -> Self;
37	}
38	
39	/// Enum representing many rounding techniques.
40	pub enum Rounding {
41	    /// Rounding toward negative infinity.
42	    Floor,
43	    /// Rounding toward positive infinity.
44	    Ceil,
45	}
46	
47	impl Math for U256 {
48	    fn sqrt(self) -> Self {
49	        let a = self;
50	        let one = uint!(1_U256);
51	        if a <= one {
52	            return a;
53	        }
54	
55	        // In this function, we use Newton's method to get a root of `f(x) := x²
56	        // - a`. It involves building a sequence x_n that converges
57	        // toward sqrt(a). For each iteration x_n, we also define the
58	        // error between the current value as `ε_n = | x_n - sqrt(a) |`.
59	        //
60	        // For our first estimation, we consider `e` the smallest power of 2
61	        // which is bigger than the square root of the target. (i.e.
62	        // `2**(e-1) ≤ sqrt(a) < 2**e`). We know that `e ≤ 128` because
63	        // `(2¹²⁸)² = 2²⁵⁶` is bigger than any uint256.
64	        //
65	        // By noticing that
66	        // `2**(e-1) ≤ sqrt(a) < 2**e → (2**(e-1))² ≤ a < (2**e)² → 2**(2*e-2) ≤
67	        // a < 2**(2*e)` we can deduce that `e - 1` is `log2(a) / 2`. We
68	        // can thus compute `x_n = 2**(e-1)` using a method similar to
69	        // the msb function.
70	        let mut aa = a;
71	        let mut xn = one;
72	
73	        if aa >= (one << 128) {
74	            aa >>= 128;
75	            xn <<= 64;
76	        }
77	        if aa >= (one << 64) {
78	            aa >>= 64;
79	            xn <<= 32;
80	        }
81	        if aa >= (one << 32) {
82	            aa >>= 32;
83	            xn <<= 16;
84	        }
85	        if aa >= (one << 16) {
86	            aa >>= 16;
87	            xn <<= 8;
88	        }
89	        if aa >= (one << 8) {
90	            aa >>= 8;
91	            xn <<= 4;
92	        }
93	        if aa >= (one << 4) {
94	            aa >>= 4;
95	            xn <<= 2;
96	        }
97	        if aa >= (one << 2) {
98	            xn <<= 1;
99	        }
100	
101	        // We now have x_n such that `x_n = 2**(e-1) ≤ sqrt(a) < 2**e = 2 *
102	        // x_n`. This implies ε_n ≤ 2**(e-1).
103	        //
104	        // We can refine our estimation by noticing that the middle of that
105	        // interval minimizes the error. If we move x_n to equal
106	        // 2**(e-1) + 2**(e-2), then we reduce the error to ε_n ≤
107	        // 2**(e-2). This is going to be our x_0 (and ε_0)
108	        xn = (uint!(3_U256) * xn) >> 1; // ε_0 := | x_0 - sqrt(a) | ≤ 2**(e-2)
109	
110	        // From here, Newton's method give us:
111	        // x_{n+1} = (x_n + a / x_n) / 2
112	        //
113	        // One should note that:
114	        // x_{n+1}² - a = ((x_n + a / x_n) / 2)² - a
115	        //              = ((x_n² + a) / (2 * x_n))² - a
116	        //              = (x_n⁴ + 2 * a * x_n² + a²) / (4 * x_n²) - a
117	        //              = (x_n⁴ + 2 * a * x_n² + a² - 4 * a * x_n²) / (4 * x_n²)
118	        //              = (x_n⁴ - 2 * a * x_n² + a²) / (4 * x_n²)
119	        //              = (x_n² - a)² / (2 * x_n)²
120	        //              = ((x_n² - a) / (2 * x_n))²
121	        //              ≥ 0
122	        // Which proves that for all n ≥ 1, sqrt(a) ≤ x_n
123	        //
124	        // This gives us the proof of quadratic convergence of the sequence:
125	        // ε_{n+1} = | x_{n+1} - sqrt(a) |
126	        //         = | (x_n + a / x_n) / 2 - sqrt(a) |
127	        //         = | (x_n² + a - 2*x_n*sqrt(a)) / (2 * x_n) |
128	        //         = | (x_n - sqrt(a))² / (2 * x_n) |
129	        //         = | ε_n² / (2 * x_n) |
130	        //         = ε_n² / | (2 * x_n) |
131	        //
132	        // For the first iteration, we have a special case where x_0 is known:
133	        // ε_1 = ε_0² / | (2 * x_0) |
134	        //     ≤ (2**(e-2))² / (2 * (2**(e-1) + 2**(e-2)))
135	        //     ≤ 2**(2*e-4) / (3 * 2**(e-1))
136	        //     ≤ 2**(e-3) / 3
137	        //     ≤ 2**(e-3-log2(3))
138	        //     ≤ 2**(e-4.5)
139	        //
140	        // For the following iterations, we use the fact that, 2**(e-1) ≤
141	        // sqrt(a) ≤ x_n: ε_{n+1} = ε_n² / | (2 * x_n) |
142	        //         ≤ (2**(e-k))² / (2 * 2**(e-1))
143	        //         ≤ 2**(2*e-2*k) / 2**e
144	        //         ≤ 2**(e-2*k)
145	        xn = (xn + a / xn) >> 1; // ε_1 := | x_1 - sqrt(a) | ≤ 2**(e-4.5)  -- special case, see above
146	        xn = (xn + a / xn) >> 1; // ε_2 := | x_2 - sqrt(a) | ≤ 2**(e-9)    -- general case with k = 4.5
147	        xn = (xn + a / xn) >> 1; // ε_3 := | x_3 - sqrt(a) | ≤ 2**(e-18)   -- general case with k = 9
148	        xn = (xn + a / xn) >> 1; // ε_4 := | x_4 - sqrt(a) | ≤ 2**(e-36)   -- general case with k = 18
149	        xn = (xn + a / xn) >> 1; // ε_5 := | x_5 - sqrt(a) | ≤ 2**(e-72)   -- general case with k = 36
150	        xn = (xn + a / xn) >> 1; // ε_6 := | x_6 - sqrt(a) | ≤ 2**(e-144)  -- general case with k = 72
151	
152	        // Because e ≤ 128 (as discussed during the first estimation phase), we
153	        // know have reached a precision ε_6 ≤ 2**(e-144) < 1. Given
154	        // we're operating on integers, then we can ensure that xn is
155	        // now either sqrt(a) or sqrt(a) + 1.
156	        xn - U256::from(xn > a / xn)
157	    }
158	
159	    fn average(self, rhs: Self) -> Self {
160	        // `(a + b) / 2` can overflow, so instead we compute
161	        // `(2 * (a & b) + (a ^ b)) / 2`.
162	        //
163	        // `a ^ b` computes the sum without carries while `2 * (a & b)` singles
164	        // out the carries, so `2 * (a & b) + (a ^ b) == a + b`. Sum with no
165	        // carries + carries.
166	        (self & rhs) + ((self ^ rhs) >> 1)
167	    }
168	
169	    fn mul_div(self, y: Self, denominator: Self, rounding: Rounding) -> Self {
170	        assert!(
171	            !denominator.is_zero(),
172	            "division by U256::ZERO in `Math::mul_div`"
173	        );
174	
175	        let prod = U512::from(self)
176	            .checked_mul(U512::from(y))
177	            .expect("should not panic with `U256` * `U256`");
178	
179	        // Adjust for rounding if needed.
180	        let adjusted = match rounding {
181	            Rounding::Floor => prod, // No adjustment for Rounding::Floor
182	            Rounding::Ceil => prod
183	                .checked_add(U512::from(denominator) - U512::from(1))
184	                .expect("should not exceed `U512`"),
185	        };
186	
187	        let result = adjusted
188	            .checked_div(U512::from(denominator))
189	            .expect("should not panic with `U512` / `U512`");
190	
191	        if result > U512::from(U256::MAX) {
192	            panic!("should fit into `U256` in `Math::mul_div`");
193	        } else {
194	            U256::from(result)
195	        }
196	    }
197	}
