1	//! Contract module for managing `U256` to boolean mapping in a compact and
2	//! efficient way, provided the keys are sequential. Largely inspired by
3	//! Uniswap's [merkle-distributor].
4	//!
5	//! `BitMap` packs 256 booleans across each bit of a single 256-bit slot of
6	//! `U256` type. Hence, booleans corresponding to 256 _sequential_ indices
7	//! would only consume a single slot, unlike the regular boolean which would
8	//! consume an entire slot for a single value.
9	//!
10	//! This results in gas savings in two ways:
11	//!
12	//! - Setting a zero value to non-zero only once every 256 times
13	//! - Accessing the same warm slot for every 256 _sequential_ indices
14	//!
15	//! [merkle-distributor]: https://github.com/Uniswap/merkle-distributor/blob/master/contracts/MerkleDistributor.sol
16	use alloc::{vec, vec::Vec};
17	
18	use alloy_primitives::{uint, U256};
19	use stylus_sdk::{prelude::*, storage::{StorageMap, StorageU256}};
20	const ONE: U256 = uint!(0x1_U256);
21	const HEX_FF: U256 = uint!(0xff_U256);
22	
23	/// State of a [`BitMap`] contract.
24	#[storage]
25	pub struct BitMap {
26	    /// Inner laying mapping.
27	    pub(crate) data: StorageMap<U256, StorageU256>}
28	
29	impl BitMap {
30	    /// Returns whether the bit at `index` is set.
31	    ///
32	    /// # Arguments
33	    ///
34	    /// * `index` - index of the boolean value in the bit map.
35	    #[must_use]
36	    pub fn get(&self, index: U256) -> bool {
37	        let bucket = Self::get_bucket(index);
38	        let mask = Self::get_mask(index);
39	        let value = self.data.get(bucket);
40	        (value & mask) != U256::ZERO
41	    }
42	
43	    /// Sets the bit at `index` to the boolean `value`.
44	    ///
45	    /// # Arguments
46	    ///
47	    /// * `index` - index of boolean value in the bit map.
48	    /// * `value` - boolean value to set in the bit map.
49	    pub fn set_to(&mut self, index: U256, value: bool) {
50	        if value {
51	            self.set(index);
52	        } else {
53	            self.unset(index);
54	        }
55	    }
56	
57	    /// Sets the bit at `index`.
58	    ///
59	    /// # Arguments
60	    ///
61	    /// * `index` - index of boolean value that should be set `true`.
62	    pub fn set(&mut self, index: U256) {
63	        let bucket = Self::get_bucket(index);
64	        let mask = Self::get_mask(index);
65	        let mut value = self.data.setter(bucket);
66	        let prev = value.get();
67	        value.set(prev | mask);
68	    }
69	
70	    /// Unsets the bit at `index`.
71	    ///
72	    /// # Arguments
73	    ///
74	    /// * `index` - index of boolean value that should be set `false`.
75	    pub fn unset(&mut self, index: U256) {
76	        let bucket = Self::get_bucket(index);
77	        let mask = Self::get_mask(index);
78	        let mut value = self.data.setter(bucket);
79	        let prev = value.get();
80	        value.set(prev & !mask);
81	    }
82	
83	    /// Get mask of value in the bucket.
84	    fn get_mask(index: U256) -> U256 {
85	        ONE << (index & HEX_FF)
86	    }
87	
88	    /// Get bucket index.
89	    fn get_bucket(index: U256) -> U256 {
90	        index >> 8
91	    }
92	}
