46	/// State of a [`Trace`] contract.
47	#[storage]
48	pub struct Trace<S: Size> {
49	    /// Stores checkpoints in a dynamic array sorted by key.
50	    pub(crate) checkpoints: StorageVec<Checkpoint<S>>}
51	
52	/// State of a [`Checkpoint`] contract.
53	#[storage]
54	pub struct Checkpoint<S: Size> {
55	    /// The key of the checkpoint. Used as a sorting key.
56	    pub(crate) key: S::KeyStorage,
57	    /// The value corresponding to the key.
58	    pub(crate) value: S::ValueStorage}
59	
60	impl<S: Size> Trace<S> {
61	    /// Pushes a (`key`, `value`) pair into a `Trace` so that it is
62	    /// stored as the checkpoint.
63	    ///
64	    /// Returns the previous value and the new value as an ordered pair.
65	    ///
66	    /// IMPORTANT: Never accept `key` as user input, since an arbitrary
67	    /// `U96::MAX` key set will disable the library.
68	    ///
69	    /// # Arguments
70	    ///
71	    /// * `&mut self` - Write access to the checkpoint's state.
72	    /// * `key` - Latest checkpoint key to insert.
73	    /// * `value` - Checkpoint value corresponding to `key`.
74	    ///
75	    /// # Errors
76	    ///
77	    /// * [`Error::CheckpointUnorderedInsertion`] - If the `key` is lower than
78	    ///   previously pushed checkpoint's key (necessary to maintain sorted
79	    ///   order).
80	    pub fn push(
81	        &mut self,
82	        key: S::Key,
83	        value: S::Value,
84	    ) -> Result<(S::Value, S::Value), Error> {
85	        self._insert(key, value)
86	    }
87	
88	    /// Returns the value in the first (oldest) checkpoint with key greater or
89	    /// equal than the search key, or `S::Value::ZERO` if there is none.
90	    ///
91	    /// # Arguments
92	    ///
93	    /// * `&self` - Read access to the checkpoint's state.
94	    /// * `key` - Checkpoint's key to lookup.
95	    pub fn lower_lookup(&self, key: S::Key) -> S::Value {
96	        let len = self.length();
97	        let pos = self._lower_binary_lookup(key, U256::ZERO, len);
98	        if pos == len {
99	            S::Value::ZERO
100	        } else {
101	            self._index(pos).value.get()
102	        }
103	    }
104	
105	    /// Returns the value in the last (most recent) checkpoint with key
106	    /// lower or equal than the search key, or `S::Value::ZERO` if there is
107	    /// none.
108	    ///
109	    /// # Arguments
110	    ///
111	    /// * `&self` - Read access to the checkpoint's state.
112	    /// * `key` - Checkpoint's key to lookup.
113	    pub fn upper_lookup(&self, key: S::Key) -> S::Value {
114	        let len = self.length();
115	        let pos = self._upper_binary_lookup(key, U256::ZERO, len);
116	        if pos == U256::ZERO {
117	            S::Value::ZERO
118	        } else {
119	            self._index(pos - uint!(1_U256)).value.get()
120	        }
121	    }
122	
123	    /// Returns the value in the last (most recent) checkpoint with key lower or
124	    /// equal than the search key, or `S::Value::ZERO` if there is none.
125	    ///
126	    /// This is a variant of [`Self::upper_lookup`] that is optimized to find
127	    /// "recent" checkpoints (checkpoints with high keys).
128	    ///
129	    /// # Arguments
130	    ///
131	    /// * `&self` - Read access to the checkpoint's state.
132	    /// * `key` - Checkpoint's key to query.
133	    pub fn upper_lookup_recent(&self, key: S::Key) -> S::Value {
134	        let len = self.length();
135	
136	        let mut low = U256::ZERO;
137	        let mut high = len;
138	
139	        if len > uint!(5_U256) {
140	            let mid = len - len.sqrt();
141	            if key < self._index(mid).key.get() {
142	                high = mid;
143	            } else {
144	                low = mid + uint!(1_U256);
145	            }
146	        }
147	
148	        let pos = self._upper_binary_lookup(key, low, high);
149	
150	        if pos == U256::ZERO {
151	            S::Value::ZERO
152	        } else {
153	            self._index(pos - uint!(1_U256)).value.get()
154	        }
155	    }
156	
157	    /// Returns the value in the most recent checkpoint, or `S::Value::ZERO` if
158	    /// there are no checkpoints.
159	    ///
160	    /// # Arguments
161	    ///
162	    /// * `&self` - Read access to the checkpoint's state.
163	    pub fn latest(&self) -> S::Value {
164	        let pos = self.length();
165	        if pos == U256::ZERO {
166	            S::Value::ZERO
167	        } else {
168	            self._index(pos - uint!(1_U256)).value.get()
169	        }
170	    }
171	
172	    /// Returns whether there is a checkpoint in the structure (i.g. it is not
173	    /// empty), and if so, the key and value in the most recent checkpoint.
174	    /// Otherwise, [`None`] will be returned.
175	    ///
176	    /// # Arguments
177	    ///
178	    /// * `&self` - Read access to the checkpoint's state.
179	    pub fn latest_checkpoint(&self) -> Option<(S::Key, S::Value)> {
180	        let pos = self.length();
181	        if pos == U256::ZERO {
182	            None
183	        } else {
184	            let checkpoint = self._index(pos - uint!(1_U256));
185	            Some((checkpoint.key.get(), checkpoint.value.get()))
186	        }
187	    }
188	
189	    /// Returns the number of checkpoints.
190	    ///
191	    /// # Arguments
192	    ///
193	    /// * `&self` - Read access to the checkpoint's state.
194	    pub fn length(&self) -> U256 {
195	        U256::from(self.checkpoints.len())
196	    }
197	
198	    /// Returns checkpoint at given position.
199	    ///
200	    /// # Panics
201	    ///
202	    /// If `pos` exceeds [`Self::length`].
203	    ///
204	    /// # Arguments
205	    ///
206	    /// * `&self` - Read access to the checkpoint's state.
207	    /// * `pos` - Index of the checkpoint.
208	    pub fn at(&self, pos: U32) -> (S::Key, S::Value) {
209	        let guard = self.checkpoints.get(pos).unwrap_or_else(|| {
210	            panic!("should get checkpoint at index `{pos}`")
211	        });
212	        (guard.key.get(), guard.value.get())
213	    }
214	
215	    /// Pushes a (`key`, `value`) pair into an ordered list of checkpoints,
216	    /// either by inserting a new checkpoint, or by updating the last one.
217	    /// Returns the previous value and the new value as an ordered pair.
218	    ///
219	    /// # Arguments
220	    ///
221	    /// * `&mut self` - Write access to the checkpoint's state.
222	    /// * `key` - The key of the checkpoint to insert.
223	    /// * `value` - Checkpoint value corresponding to insertion `key`.
224	    ///
225	    /// # Errors
226	    ///
227	    /// * [`Error::CheckpointUnorderedInsertion`] - If the `key` is lower than
228	    ///   the previously inserted one.
229	    fn _insert(
230	        &mut self,
231	        key: S::Key,
232	        value: S::Value,
233	    ) -> Result<(S::Value, S::Value), Error> {
234	        let pos = self.length();
235	        if pos > U256::ZERO {
236	            let last = self._index(pos - uint!(1_U256));
237	            let last_key = last.key.get();
238	            let last_value = last.value.get();
239	
240	            // Checkpoint keys must be non-decreasing.
241	            if last_key > key {
242	                return Err(CheckpointUnorderedInsertion {}.into());
243	            }
244	
245	            // Update or push new checkpoint
246	            if last_key == key {
247	                self._index_mut(pos - uint!(1_U256)).value.set(value);
248	            } else {
249	                self._unchecked_push(key, value);
250	            }
251	            Ok((last_value, value))
252	        } else {
253	            self._unchecked_push(key, value);
254	            Ok((S::Value::ZERO, value))
255	        }
256	    }
257	
258	    /// Return the index of the last (most recent) checkpoint with key lower or
259	    /// equal than the search key, or `high` if there is none.
260	    ///
261	    /// Indexes `low` and `high` define a section where to do the search, with
262	    /// inclusive `low` and exclusive `high`.
263	    ///
264	    /// WARNING: `high` should not be greater than the array's length.
265	    ///
266	    /// # Arguments
267	    ///
268	    /// * `&self` - Read access to the checkpoint's state.
269	    /// * `key` - Checkpoint key to lookup.
270	    /// * `low` - Inclusive index where search begins.
271	    /// * `high` - Exclusive index where search ends.
272	    fn _upper_binary_lookup(
273	        &self,
274	        key: S::Key,
275	        mut low: U256,
276	        mut high: U256,
277	    ) -> U256 {
278	        while low < high {
279	            let mid = low.average(high);
280	            if self._index(mid).key.get() > key {
281	                high = mid;
282	            } else {
283	                low = mid + uint!(1_U256);
284	            }
285	        }
286	        high
287	    }
288	
289	    /// Return the index of the first (oldest) checkpoint with key is greater or
290	    /// equal than the search key, or `high` if there is none.
291	    ///
292	    /// Indexes `low` and `high` define a section where to do the search, with
293	    /// inclusive `low` and exclusive `high`.
294	    ///
295	    /// WARNING: `high` should not be greater than the array's length.
296	    ///
297	    /// # Arguments
298	    ///
299	    /// * `&self` - Read access to the checkpoint's state.
300	    /// * `key` - Checkpoint key to lookup.
301	    /// * `low` - Inclusive index where search begins.
302	    /// * `high` - Exclusive index where search ends.
303	    fn _lower_binary_lookup(
304	        &self,
305	        key: S::Key,
306	        mut low: U256,
307	        mut high: U256,
308	    ) -> U256 {
309	        while low < high {
310	            let mid = low.average(high);
311	            if self._index(mid).key.get() < key {
312	                low = mid + uint!(1_U256);
313	            } else {
314	                high = mid;
315	            }
316	        }
317	        high
318	    }
319	
320	    /// Immutable access on an element of the checkpoint's array. The position
321	    /// is assumed to be within bounds.
322	    ///
323	    /// # Arguments
324	    ///
325	    /// * `&self` - Read access to the checkpoint's state.
326	    /// * `pos` - Index of the checkpoint.
327	    ///
328	    /// # Panics
329	    ///
330	    /// * If `pos` exceeds [`Self::length`].
331	    fn _index(&self, pos: U256) -> StorageGuard<'_, Checkpoint<S>> {
332	        self.checkpoints
333	            .get(pos)
334	            .unwrap_or_else(|| panic!("should get checkpoint at index `{pos}`"))
335	    }
336	
337	    /// Mutable access on an element of the checkpoint's array. The position is
338	    /// assumed to be within bounds.
339	    ///
340	    /// # Arguments
341	    ///
342	    /// * `&mut self` - Write access to the checkpoint's state.
343	    /// * `pos` - Index of the checkpoint.
344	    ///
345	    /// # Panics
346	    ///
347	    /// * If `pos` exceeds [`Self::length`].
348	    fn _index_mut(&mut self, pos: U256) -> StorageGuardMut<'_, Checkpoint<S>> {
349	        self.checkpoints
350	            .setter(pos)
351	            .unwrap_or_else(|| panic!("should get checkpoint at index `{pos}`"))
352	    }
353	
354	    /// Append a checkpoint without checking if the sorted order is kept.
355	    ///
356	    /// # Arguments
357	    ///
358	    /// * `&mut self` - Write access to the checkpoint's state.
359	    /// * `key` - Checkpoint key to insert.
360	    /// * `value` - Checkpoint value corresponding to insertion `key`.
361	    fn _unchecked_push(&mut self, key: S::Key, value: S::Value) {
362	        let mut new_checkpoint = self.checkpoints.grow();
363	        new_checkpoint.key.set(key);
364	        new_checkpoint.value.set(value);
365	    }
366	}
