1	//! Smart contract for managing sets.
2	
3	pub mod element;
4	
5	/// Sets have the following properties:
6	///
7	/// * Elements are added, removed, and checked for existence in constant
8	///   time (O(1)).
9	/// * Elements are enumerated in O(n). No guarantees are made on the
10	///   ordering.
11	/// * Set can be cleared (all elements removed) in O(n).
12	use alloc::{vec, vec::Vec};
13	
14	use alloy_primitives::U256;
15	pub use element::{Accessor, Element};
16	use stylus_sdk::{prelude::*, storage::{StorageMap, StorageType, StorageU256, StorageVec}};
17	
18	/// State of an [`EnumerableSet`] contract.
19	#[storage]
20	pub struct EnumerableSet<T: Element> {
21	    /// Values in the set.
22	    values: StorageVec<T::StorageElement>,
23	    /// Position is the index of the value in the `values` array plus 1.
24	    /// Position 0 is used to mean a value is not in the set.
25	    positions: StorageMap<T, StorageU256>}
26	
27	impl<T: Element> EnumerableSet<T> {
28	    /// Adds a value to a set.
29	    ///
30	    /// Returns true if the `value` was added to the set, that is if it was not
31	    /// already present.
32	    ///
33	    /// # Arguments
34	    ///
35	    /// * `&mut self` - Write access to the set's state.
36	    /// * `value` - The value to add to the set.
37	    pub fn add(&mut self, value: T) -> bool {
38	        if self.contains(value) {
39	            false
40	        } else {
41	            self.values.push(value);
42	
43	            let position = self.length();
44	            self.positions.setter(value).set(position);
45	            true
46	        }
47	    }
48	
49	    /// Removes a `value` from a set.
50	    ///
51	    /// Returns true if the `value` was removed from the set, that is if it was
52	    /// present.
53	    ///
54	    /// # Arguments
55	    ///
56	    /// * `&mut self` - Write access to the set's state.
57	    /// * `value` - The value to remove from the set.
58	    #[allow(clippy::missing_panics_doc)]
59	    pub fn remove(&mut self, value: T) -> bool {
60	        let position = self.positions.get(value);
61	
62	        if position.is_zero() {
63	            false
64	        } else {
65	            let value_index = position - U256::ONE;
66	            let last_index = self.length() - U256::ONE;
67	
68	            if value_index != last_index {
69	                let last_value = self
70	                    .values
71	                    .get(last_index)
72	                    .expect("element at `last_index` must exist");
73	
74	                self.values
75	                    .setter(value_index)
76	                    .expect(
77	                        "element at `value_index` must exist - is being removed",
78	                    )
79	                    .set(last_value);
80	
81	                self.positions.setter(last_value).set(position);
82	            }
83	
84	            self.values.pop();
85	
86	            self.positions.delete(value);
87	
88	            true
89	        }
90	    }
91	
92	    /// Remove all values from a set.
93	    ///
94	    /// # WARNING
95	    ///
96	    /// This function has an unbounded cost that scales with set size.
97	    /// Developers should keep in mind that using it may render the function
98	    /// uncallable if the set grows to the point where clearing it consumes too
99	    /// much gas to fit in a block.
100	    ///
101	    /// # Arguments
102	    ///
103	    /// * `&mut self` - Write access to the set's state.
104	    #[allow(clippy::missing_panics_doc)]
105	    pub fn clear(&mut self) {
106	        for idx in 0..self.values.len() {
107	            let v = self
108	                .values
109	                .get(idx)
110	                .expect("element at index: {idx} must exist");
111	            self.positions.delete(v);
112	        }
113	
114	        self.values.erase();
115	    }
116	
117	    /// Returns true if the `value` is in the set.
118	    ///
119	    /// # Arguments
120	    ///
121	    /// * `&self` - Read access to the set's state.
122	    /// * `value` - The value to check for in the set.
123	    #[must_use]
124	    pub fn contains(&self, value: T) -> bool {
125	        !self.positions.get(value).is_zero()
126	    }
127	
128	    /// Returns the number of values in the set.
129	    ///
130	    /// Note this implementation's maximum length will technically be `usize`
131	    /// because that is the type returned by the underlying
132	    /// [`StorageVec::len`].
133	    ///
134	    /// # Arguments
135	    ///
136	    /// * `&self` - Read access to the set's state.
137	    #[must_use]
138	    pub fn length(&self) -> U256 {
139	        U256::from(self.values.len())
140	    }
141	
142	    /// Returns the value stored at position `index` in the set.
143	    ///
144	    /// Note that there are no guarantees on the ordering of values inside the
145	    /// array, and it may change when more values are added or removed.
146	    ///
147	    /// # Arguments
148	    ///
149	    /// * `&self` - Read access to the set's state.
150	    /// * `index` - The index of the value to return.
151	    #[must_use]
152	    pub fn at(&self, index: U256) -> Option<T> {
153	        self.values.get(index)
154	    }
155	
156	    /// Returns the entire set in an array.
157	    ///
158	    /// # WARNING
159	    ///
160	    /// This operation will copy the entire storage to memory, which can be
161	    /// quite expensive. This is designed to mostly be used by view
162	    /// accessors that are queried without any gas fees. Developers should keep
163	    /// in mind that this function has an unbounded cost, and using it as
164	    /// part of a state-changing function may render the function uncallable
165	    /// if the set grows to a point where copying to memory consumes too much
166	    /// gas to fit in a block.
167	    ///
168	    /// # Arguments
169	    ///
170	    /// * `&self` - Read access to the set's state.
171	    #[allow(clippy::missing_panics_doc)]
172	    #[must_use]
173	    pub fn values(&self) -> Vec<T> {
174	        let mut values = Vec::new();
175	        for idx in 0..self.values.len() {
176	            values.push(
177	                self.values
178	                    .get(idx)
179	                    .expect("element at index: {idx} must exist"),
180	            );
181	        }
182	        values
183	    }
184	
185	    /// Returns a slice of the set in an array.
186	    ///
187	    /// This function allows querying subsets of large sets to avoid
188	    /// out-of-gas scenarios when the full set would be too expensive
189	    /// to return in a single call.
190	    ///
191	    /// # WARNING
192	    ///
193	    /// This operation will copy the entire storage to memory, which can be
194	    /// quite expensive. This is designed to mostly be used by view
195	    /// accessors that are queried without any gas fees. Developers should keep
196	    /// in mind that this function has an unbounded cost, and using it as
197	    /// part of a state-changing function may render the function uncallable
198	    /// if the set grows to a point where copying to memory consumes too much
199	    /// gas to fit in a block.
200	    ///
201	    /// # Arguments
202	    ///
203	    /// * `&self` - Read access to the set's state.
204	    /// * `start` - The starting index (inclusive).
205	    /// * `end` - The ending index (exclusive).
206	    #[allow(clippy::missing_panics_doc)]
207	    #[must_use]
208	    pub fn values_slice(&self, start: U256, end: U256) -> Vec<T> {
209	        let len = self.length();
210	
211	        // clamp parameters to valid ranges as in Solidity implementation: <https://github.com/OpenZeppelin/openzeppelin-contracts/blob/448538259f1feeb24f3e3201115d70818ba876cb/contracts/utils/structs/EnumerableSet.sol#L189>.
212	        let end = core::cmp::min(end, len);
213	        let start = core::cmp::min(start, end);
214	
215	        // Uses optimized native iteration for typical cases where indices
216	        // fit within [`usize`] bounds. Falls back to [`U256`] arithmetic for
217	        // extremely large indices (theoretical edge case).
218	        if let (Ok(start_idx), Ok(end_idx)) =
219	            (usize::try_from(start), usize::try_from(end))
220	        {
221	            // fast path: use native [`usize`] iteration with iterator
222	            // chains.
223	            (start_idx..end_idx)
224	                .map(|idx| {
225	                    self.at(U256::from(idx))
226	                        .expect("element at index: {idx} must exist")
227	                })
228	                .collect()
229	        } else {
230	            // slow path: pure [`U256`] arithmetic for extremely large indices.
231	            let mut result = Vec::new();
232	            let mut current = start;
233	
234	            while current < end {
235	                let value = self
236	                    .at(current)
237	                    .expect("element at index: {current} must exist");
238	                result.push(value);
239	
240	                current += U256::ONE;
241	            }
242	
243	            result
244	        }
245	    }
246	}
