1	//! Contains generic size utilities for enumerable set storage contract.
2	
3	use alloy_primitives::{Address, B256, U128, U16, U256, U32, U64, U8};
4	use stylus_sdk::{prelude::{Erase, SimpleStorageType, StorageType}, storage::{
5	        StorageAddress, StorageB256, StorageKey, StorageU128, StorageU16, StorageU256, StorageU32, StorageU64, StorageU8}};
6	
7	/// Trait that associate set element with storage type.
8	pub trait Element: StorageKey + Copy {
9	    /// Set element type in storage.
10	    type StorageElement: for<'a> StorageType<Wraps<'a> = Self>
11	        + Accessor<Wraps = Self>
12	        + for<'a> SimpleStorageType<'a>
13	        + Erase;
14	}
15	
16	/// Abstracts accessor inside the contract.
17	pub trait Accessor {
18	    /// Type of the number associated with the storage type.
19	    type Wraps;
20	
21	    /// Gets underlying element [`Self::Wraps`] from persistent storage.
22	    fn get(&self) -> Self::Wraps;
23	
24	    /// Sets underlying element [`Self::Wraps`] in persistent storage.
25	    fn set(&mut self, value: Self::Wraps);
26	}
27	
28	/// Implements [`Element`] and [`Accessor`] traits for a given type.
29	macro_rules! impl_element_and_accessor {
30	    ($ty:ty, $storage_ty:ty) => {
31	        impl Element for $ty {
32	            type StorageElement = $storage_ty;
33	        }
34	
35	        impl Accessor for $storage_ty {
36	            type Wraps = $ty;
37	
38	            fn get(&self) -> Self::Wraps {
39	                self.get()
40	            }
41	
42	            fn set(&mut self, value: Self::Wraps) {
43	                self.set(value);
44	            }
45	        }
46	    };
47	}
48	
49	impl_element_and_accessor!(Address, StorageAddress);
50	impl_element_and_accessor!(B256, StorageB256);
51	impl_element_and_accessor!(U8, StorageU8);
52	impl_element_and_accessor!(U16, StorageU16);
53	impl_element_and_accessor!(U32, StorageU32);
54	impl_element_and_accessor!(U64, StorageU64);
55	impl_element_and_accessor!(U128, StorageU128);
56	impl_element_and_accessor!(U256, StorageU256);
