#[cfg(test)]
mod tests {
    use alloy_primitives::uint;
    use stylus_sdk::testing::TestVM;

    use super::{
        generic_size::S160, CheckpointUnorderedInsertion, Error, Trace,
    };
    use crate::test_utils::ALICE;

    #[test]
    fn push() {
        let vm = TestVM::default();
        vm.set_sender(ALICE);
        let mut checkpoint = Trace::<S160>::from(&vm);

        let first_key = uint!(1_U96);
        let first_value = uint!(11_U160);

        let second_key = uint!(2_U96);
        let second_value = uint!(22_U160);

        let third_key = uint!(3_U96);
        let third_value = uint!(33_U160);

        checkpoint.push(first_key, first_value)
            .expect("push first");
        checkpoint.push(second_key, second_value)
            .expect("push second");
        checkpoint.push(third_key, third_value)
            .expect("push third");

        assert_eq!(checkpoint.length(), uint!(3_U256));

        assert_eq!(
            checkpoint.at(uint!(0_U32)),
            (first_key, first_value)
        );
        assert_eq!(
            checkpoint.at(uint!(1_U32)),
            (second_key, second_value)
        );
        assert_eq!(
            checkpoint.at(uint!(2_U32)),
            (third_key, third_value)
        );
    }

    #[test]
    fn push_same_value() {
        let vm = TestVM::default();
        vm.set_sender(ALICE);
        let mut checkpoint = Trace::<S160>::from(&vm);

        let first_key = uint!(1_U96);
        let first_value = uint!(11_U160);

        let second_key = uint!(2_U96);
        let second_value = uint!(22_U160);

        let third_key = uint!(2_U96);
        let third_value = uint!(222_U160);

        checkpoint.push(first_key, first_value)
            .expect("push first");
        checkpoint.push(second_key, second_value)
            .expect("push second");
        checkpoint.push(third_key, third_value)
            .expect("push third");

        assert_eq!(
            checkpoint.length(),
            uint!(2_U256),
            "two checkpoints should be stored since third_value overrides second_value"
        );

        assert_eq!(
            checkpoint.at(uint!(0_U32)),
            (first_key, first_value)
        );
        assert_eq!(
            checkpoint.at(uint!(1_U32)),
            (third_key, third_value)
        );
    }
    #[test]
    fn lower_lookup() {
        let vm = TestVM::default();
        vm.set_sender(ALICE);
        let mut checkpoint = Trace::<S160>::from(&vm);

        checkpoint.push(uint!(1_U96), uint!(11_U160))
            .expect("push first");
        checkpoint.push(uint!(3_U96), uint!(33_U160))
            .expect("push second");

