//! Scratch tests (NOT part of the repo): validate the migrated address helpers.
use alloy_primitives::{address, Address};
use stylus_sdk::{prelude::*, testing::TestVM};

use crate::{
    test_utils::{ALICE, BOB},
    utils::address::{AddressUtils, Error},
};

#[storage]
#[entrypoint]
struct Caller;

#[public]
impl Caller {}

const TARGET: Address = address!("00000000000000000000000000000000000c0de0");

#[test]
fn has_code_works() {
    let vm = TestVM::default();
    let c = Caller::from(&vm);
    assert!(!AddressUtils::has_code(&c, TARGET));
    vm.set_code(TARGET, vec![0x60]);
    assert!(AddressUtils::has_code(&c, TARGET));
}

#[test]
fn delegate_call_ok_returns_data() {
    let vm = TestVM::default();
    vm.set_sender(ALICE);
    let mut c = Caller::from(&vm);
    vm.mock_delegate_call(TARGET, vec![1, 2, 3], Ok(vec![9, 9]));
    let r = AddressUtils::function_delegate_call(&mut c, TARGET, &[1, 2, 3]);
    assert_eq!(r.unwrap(), vec![9, 9]);
}

#[test]
fn delegate_call_empty_return_no_code_is_empty_code() {
    let vm = TestVM::default();
    let mut c = Caller::from(&vm);
    vm.mock_delegate_call(TARGET, vec![1], Ok(vec![]));
    let r = AddressUtils::function_delegate_call(&mut c, TARGET, &[1]);
    assert!(matches!(r, Err(Error::EmptyCode(e)) if e.target == TARGET));
}

#[test]
fn delegate_call_empty_return_with_code_is_ok() {
    let vm = TestVM::default();
    let mut c = Caller::from(&vm);
    vm.set_code(TARGET, vec![0x60]);
    vm.mock_delegate_call(TARGET, vec![1], Ok(vec![]));
    let r = AddressUtils::function_delegate_call(&mut c, TARGET, &[1]);
    assert_eq!(r.unwrap(), Vec::<u8>::new());
}

#[test]
fn delegate_call_revert_without_reason_is_failed_call() {
    let vm = TestVM::default();
    let mut c = Caller::from(&vm);
    vm.mock_delegate_call(TARGET, vec![1], Err(vec![]));
    let r = AddressUtils::function_delegate_call(&mut c, TARGET, &[1]);
    assert!(matches!(r, Err(Error::FailedCall(_))));
}

#[test]
fn delegate_call_revert_with_reason_bubbles_up() {
    let vm = TestVM::default();
    let mut c = Caller::from(&vm);
    vm.mock_delegate_call(TARGET, vec![1], Err(vec![0xde, 0xad]));
    let r = AddressUtils::function_delegate_call(&mut c, TARGET, &[1]);
    match r {
        Err(Error::FailedCallWithReason(e)) => {
            assert_eq!(e.reason.to_vec(), vec![0xde, 0xad])
        }
        other => panic!("unexpected: {:?}", other.map(|_| ())),
    }
}

#[test]
fn bob_unused_silencer() {
    let _ = BOB;
}
EOF
